DO $test$
DECLARE boss uuid; clerk uuid; sales uuid:=gen_random_uuid(); money uuid:=gen_random_uuid(); b uuid; other_branch uuid; company uuid; id uuid:=gen_random_uuid(); p jsonb; x jsonb; key text;
BEGIN
 SELECT employee INTO boss FROM contract_private.handles WHERE username='admin';
 SELECT employee INTO clerk FROM contract_private.handles WHERE username='newuser';
 SELECT br.id,co.id INTO b,company FROM app.branches br JOIN app.companies co ON co.id=br.company_id WHERE co.code='bakheet' AND br.name='الدورة';
 INSERT INTO auth.users(id,email) VALUES(sales,'sales@dummy.invalid'),(money,'money@dummy.invalid');
 p:=jsonb_build_object('company','bakheet','companies',jsonb_build_array('bakheet','imad'),'target',sales,'username','sales','name','موظف المبيعات','department','sales','role','employee','active',true,'branchRoles',jsonb_build_object(b,'employee'));
 BEGIN PERFORM public.contract_staff_assignment(boss,'create',p||jsonb_build_object('name','sales'));RAISE EXCEPTION 'single sales name accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.contract_staff_assignment(boss,'create',p);
 ASSERT jsonb_array_length(public.contract_portal(sales,'session','{}')->'companies')=2;
 PERFORM public.contract_staff_assignment(boss,'create',p||jsonb_build_object('companies',jsonb_build_array('bakheet'),'target',money,'username','finance','department','finance'));
 ASSERT jsonb_array_length(public.contract_portal(money,'session','{}')->'companies')=2;
 p:=jsonb_build_object('company','bakheet','branch','الدورة','id',id,'version',0,'data',jsonb_build_object('contractType','cash','buyer','زبون اختبار','total','300','formFees','50','formInstallmentNote','اختبار'));
 x:=public.sales_forms(sales,'form_save',p);ASSERT x->>'version'='1';
 ASSERT public.sales_forms(boss,'forms_list',p)='[]' AND public.sales_forms(money,'forms_list',p)='[]';
 BEGIN PERFORM public.sales_forms(boss,'form_read',p);RAISE EXCEPTION 'admin read another draft';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(sales,'form_publish',p);RAISE EXCEPTION 'stale publication';EXCEPTION WHEN serialization_failure THEN NULL;END;
 x:=public.sales_forms(sales,'form_publish',p||'{"version":1}');ASSERT x->>'version'='2';
 ASSERT jsonb_array_length(public.sales_forms(money,'forms_list',p))=1;
 BEGIN PERFORM public.sales_forms(money,'form_convert',p||'{"version":2}');RAISE EXCEPTION 'finance converted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(sales,'form_approve',p||'{"version":2}');RAISE EXCEPTION 'sales approved';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(boss,'form_approve',p||'{"version":2}'); RAISE EXCEPTION 'empty approval note'; EXCEPTION WHEN invalid_parameter_value THEN NULL; END;
 PERFORM public.sales_forms(boss,'form_approve',p||'{"version":2,"approval_note":"تم التدقيق"}');
 BEGIN PERFORM public.sales_forms(sales,'form_approve',p||'{"version":3,"approval_note":"wrong"}'); RAISE EXCEPTION 'another employee edited note'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 PERFORM public.sales_forms(boss,'form_approve',p||'{"version":3,"approval_note":"تم تدقيق المبلغ"}');
 ASSERT public.sales_forms(money,'form_read',p)->>'approval_note'='تم تدقيق المبلغ';
 ASSERT public.sales_forms(money,'forms_list',p||'{"month":"2000-01"}')='[]';
 ASSERT public.sales_forms(money,'forms_list',p||jsonb_build_object('month',to_char(now() AT TIME ZONE 'Asia/Baghdad','YYYY-MM')))->0->>'total'='300';
 BEGIN PERFORM public.sales_forms(money,'form_republish',p||'{"version":4}');RAISE EXCEPTION 'finance republished';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(sales,'form_republish',p||'{"version":4}');RAISE EXCEPTION 'direct edit';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(sales,'alerts',p)) n WHERE n->>'kind'='approved');
 PERFORM public.sales_forms(sales,'form_withdraw',p||'{"version":4}');
 ASSERT public.sales_forms(money,'forms_list',p)='[]';
 BEGIN PERFORM public.sales_forms(sales,'form_history',p);RAISE EXCEPTION 'sales read history';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(boss,'forms_list',p||'{"scope":"history"}')) h WHERE (h->>'id')::uuid=id);
 ASSERT public.sales_forms(sales,'forms_list',p||'{"scope":"history"}')='[]';
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(boss,'form_history',p)) h WHERE h#>>'{snapshot,approval_note}'='تم تدقيق المبلغ');
 UPDATE contract_private.sales_forms SET first_release=now()-interval '31 minutes' WHERE sales_forms.id=(p->>'id')::uuid;
 BEGIN PERFORM public.sales_forms(sales,'form_publish',p||'{"version":5}');RAISE EXCEPTION 'expired republication';EXCEPTION WHEN SQLSTATE 'P3001' THEN NULL;END;
 UPDATE contract_private.sales_forms SET first_release=now() WHERE sales_forms.id=(p->>'id')::uuid;
 UPDATE contract_private.sales_forms SET data=data||'{"notes":"private unsent text"}' WHERE sales_forms.id=(p->>'id')::uuid;
 PERFORM public.sales_forms(sales,'form_publish',p||'{"version":5}');
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(boss,'form_history',p)) h WHERE h->>'action'='form_republish');
 ASSERT NOT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(boss,'form_history',p)) h WHERE h#>>'{snapshot,data,notes}'='private unsent text');
 UPDATE contract_private.sales_forms SET first_release=now()-interval '31 minutes' WHERE sales_forms.id=(p->>'id')::uuid;
 BEGIN PERFORM public.sales_forms(sales,'form_withdraw',p||'{"version":6}');RAISE EXCEPTION 'withdrawal after deadline';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.sales_forms(boss,'form_reject',p||'{"version":6,"note":"مطلوب تصحيح"}');
 BEGIN PERFORM public.sales_forms(clerk,'form_convert',p||'{"version":7}');RAISE EXCEPTION 'converted rejected form';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(sales,'form_correct',p||'{"version":7}');RAISE EXCEPTION 'sales corrected';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.sales_forms(boss,'form_correct',p||'{"version":7}');
 x:=public.sales_forms(clerk,'form_read',p);ASSERT x->>'rejected_at' IS NULL AND x->>'approved' IS NULL;
 x:=public.sales_forms(clerk,'form_convert',p||'{"version":8}');key:=x->>'record';
 ASSERT NOT(public.sales_forms(money,'form_read',p)?'contract_key');
 ASSERT key IS NOT NULL AND public.sales_forms(clerk,'form_convert',p)->>'record'=key;
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.contract_archive(clerk,'list',p)) e WHERE e->>'record'=key AND e#>>'{draft,buyer}'='زبون اختبار' AND NOT ((e->'draft') ?| ARRAY['formFees','formInstallmentNote']));
 ASSERT NOT EXISTS(SELECT FROM jsonb_array_elements(public.contract_archive(boss,'list',p)) e WHERE e->>'record'=key);
 BEGIN PERFORM public.contract_number(boss,jsonb_build_object('company','bakheet','branch','الدورة','record',key,'mode','claim'));RAISE EXCEPTION 'private reservation';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.contract_archive(sales,'list',p);RAISE EXCEPTION 'sales contract archive';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.contract_archive(money,'download',p);RAISE EXCEPTION 'finance download';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(clerk,'move_contract',p||jsonb_build_object('destination','unknown','record',key,'version',1));RAISE EXCEPTION 'unassigned company';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 ASSERT jsonb_array_length(public.sales_forms(sales,'forms_list',p||'{"company":"imad"}'))=1;
 SELECT public.contract_portal(boss,'members','{"company":"bakheet"}') INTO x;
 SELECT e INTO x FROM jsonb_array_elements(x) e WHERE e->>'id'=clerk::text;
 PERFORM public.contract_staff_assignment(boss,'update',jsonb_build_object('company','bakheet','companies',jsonb_build_array('bakheet','imad'),'target',clerk,'username','newuser','name','كاتب','department','contracts','role','employee','active',true,'version',x->'version','branchRoles',jsonb_build_object(b,'employee')));
 PERFORM public.sales_forms(clerk,'move_contract',p||jsonb_build_object('destination','imad','record',key,'version',1));
 ASSERT EXISTS(SELECT 1 FROM jsonb_array_elements(public.contract_archive(clerk,'list','{"company":"imad"}')) e WHERE e->>'record'=key AND e#>>'{draft,companyId}'='imad');
 ASSERT EXISTS(SELECT 1 FROM jsonb_array_elements(public.contract_archive(clerk,'list','{"company":"bakheet"}')) e WHERE e->>'record'=key);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',money)::text,true);
 ASSERT NOT contract_private.read_branch(company,b);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',clerk)::text,true);
 ASSERT contract_private.read_branch(company,b);
 PERFORM public.contract_portal(boss,'brand_save','{"brand":{"id":"demo","name":"Demo"}}');
 ASSERT jsonb_array_length(public.contract_portal(sales,'session','{}')->'companies')=3;
 ASSERT public.contract_portal(boss,'layouts','{"company":"demo"}')=public.contract_portal(boss,'layouts','{"company":"imad"}');
 BEGIN PERFORM public.contract_portal(money,'brand_save','{"brand":{"id":"denied","name":"Denied"}}');RAISE EXCEPTION 'finance added brand';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 UPDATE contract_private.sales_forms SET published='2025-12-31T21:00:00Z' WHERE sales_forms.id=(p->>'id')::uuid;
 ASSERT jsonb_array_length(public.sales_forms(money,'forms_list',p||'{"month":"2026-01"}'))=1;
 ASSERT public.sales_forms(money,'forms_list',p||'{"month":"2025-12"}')='[]';
 ASSERT NOT has_function_privilege('authenticated','public.sales_forms(uuid,text,jsonb)','EXECUTE');
 -- The preparer owns the draft even when selecting a different salesperson.
 p:=jsonb_build_object('company','bakheet','branch','الدورة','id',gen_random_uuid(),'version',0,
   'data',jsonb_build_object('contractType','exchange','buyer','اختبار الاستبدال','formSellerId',sales,
    'notes','ملاحظة','exchangeOldDebt','١٠٠ دينار'));
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.form_sellers(clerk,p)) s WHERE (s->>'id')::uuid=sales);
 BEGIN PERFORM public.form_sellers(money,p);RAISE EXCEPTION 'finance seller directory';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.sales_forms(clerk,'form_save',jsonb_set(p,'{data,formSellerId}',to_jsonb(money)));
 RAISE EXCEPTION 'accepted an ineligible seller';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 PERFORM public.sales_forms(clerk,'form_save',p);
 ASSERT (public.sales_forms(clerk,'form_read',p)->>'author_name')='موظف المبيعات';
 BEGIN PERFORM public.sales_forms(sales,'form_read',p);RAISE EXCEPTION 'delegation granted private draft access';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.sales_forms(clerk,'form_publish',p||'{"version":1}');
 key:=public.sales_forms(clerk,'form_convert',p||'{"version":2}')->>'record';
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.contract_archive(clerk,'list',p)) e WHERE e->>'record'=key
   AND e->>'seller'='موظف المبيعات' AND e#>>'{draft,notes}'='ملاحظة'||chr(10)||'ذمة المركبة القديمة: ١٠٠ دينار'
   AND NOT ((e->'draft') ?| ARRAY['formSellerId','exchangeOldDebt']));
 ASSERT public.sales_forms(sales,'form_read',p)->>'author_name'='موظف المبيعات';
 BEGIN PERFORM public.sales_forms(sales,'form_remove_published',p||'{"version":3}');RAISE EXCEPTION 'sales deleted publication';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.sales_forms(boss,'form_remove_published',p||'{"version":3}');
 ASSERT jsonb_array_length(public.sales_forms(boss,'forms_list',p||'{"scope":"removed"}'))=1;
 BEGIN PERFORM public.sales_forms(money,'form_read',p);RAISE EXCEPTION 'finance read trash';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 ASSERT jsonb_array_length(public.sales_forms(boss,'form_history',p))>0;
 ASSERT NOT has_function_privilege('authenticated','public.form_devices(uuid,text,jsonb)','EXECUTE');
 -- Branch supervision is distinct from company administration.
 UPDATE app.employees e SET display_name='مسؤول تجريبي' WHERE e.id=clerk;
 UPDATE app.branch_memberships SET role='branch_manager' WHERE company_id=company AND branch_id=b AND employee_id=clerk;
 p:=jsonb_build_object('company','bakheet','branch','الدورة','id',gen_random_uuid(),'version',0,
   'data',jsonb_build_object('contractType','cash','buyer','إشعار تجريبي'));
 PERFORM public.form_devices(money,'subscribe',jsonb_build_object('endpoint','https://fcm.googleapis.com/dummy-local-test','auth',repeat('a',22),'p256dh',repeat('b',87)));
 PERFORM public.sales_forms(sales,'form_save',p);
 PERFORM public.sales_forms(sales,'form_publish',p||'{"version":1}');
 BEGIN PERFORM public.sales_forms(clerk,'form_correct',p||'{"version":2}');RAISE EXCEPTION 'manager corrected un-rejected form';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM public.sales_forms(clerk,'form_reject',p||'{"version":2,"note":"هوية"}');
 PERFORM public.sales_forms(clerk,'form_correct',p||'{"version":3}');
 PERFORM public.sales_forms(clerk,'form_approve',p||'{"version":4,"approval_note":"تم"}');
 BEGIN PERFORM public.sales_forms(clerk,'form_remove_published',p||'{"version":5}');RAISE EXCEPTION 'manager deleted publication';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 ASSERT jsonb_array_length(public.sales_forms(clerk,'form_history',p))=3;
 x:=public.form_devices(NULL,'claim','{}');
 ASSERT jsonb_array_length(x)=3 AND public.form_devices(NULL,'claim','{}')='[]';
 PERFORM public.form_devices(NULL,'finish',(x->0)||'{"outcome":"sent"}');
 PERFORM public.form_devices(NULL,'finish',(x->1)||'{"outcome":"retry"}');
 PERFORM public.form_devices(NULL,'finish',(x->2)||'{"outcome":"gone"}');
 ASSERT NOT EXISTS(SELECT FROM contract_private.form_push_queue);
 ASSERT NOT EXISTS(SELECT FROM contract_private.form_devices WHERE recipient=money);
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(sales,'alerts',p)) n WHERE n->>'kind'='rejected');
 ASSERT NOT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(money,'alerts',p)) n WHERE n->>'kind'='rejected');
 PERFORM public.sales_forms(money,'alerts_seen',p||jsonb_build_object('through',99999999));
 ASSERT NOT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(money,'alerts',p)) n WHERE (n->>'seen')::boolean=false);
 SELECT br.id INTO STRICT other_branch FROM app.branches br WHERE br.company_id=company AND br.active AND br.id<>b ORDER BY br.id LIMIT 1;
 p:=jsonb_build_object('company','bakheet','branch',(SELECT name FROM app.branches WHERE branches.id=other_branch),'id',gen_random_uuid(),'version',0,'data',jsonb_build_object('contractType','cash','buyer','فرع ثان'));
 PERFORM public.sales_forms(boss,'form_save',p);
 PERFORM public.sales_forms(boss,'form_publish',p||'{"version":1}');
 ASSERT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(clerk,'alerts',p)) n WHERE n->>'kind'='published' AND n->>'branch'=p->>'branch' AND n->>'form_id' IS NULL);
 ASSERT NOT EXISTS(SELECT FROM jsonb_array_elements(public.sales_forms(money,'alerts',p)) n WHERE n->>'branch'=p->>'branch');
 BEGIN PERFORM public.sales_forms(clerk,'form_read',p);RAISE EXCEPTION 'opened unassigned branch form';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $test$;
